465 |   function _accrue(VaultData storage s) internal returns (uint256) {
466 |     unchecked {
467 |       s.yIntercept = (_totalAssets(s)).safeCastTo88();
468 |       s.last = block.timestamp.safeCastTo40();
469 |     }
470 |     emit YInterceptChanged(s.yIntercept);
471 | 
472 |     return s.yIntercept;
473 |   }
