475 |   /**
476 |    * @notice Computes the implied value of this PublicVault. This includes interest payments that have not yet been made.
477 |    * @return The implied value for this PublicVault.
478 |    */
479 |   function totalAssets()
480 |     public
481 |     view
482 |     virtual
483 |     override(ERC4626Cloned)
484 |     returns (uint256)
485 |   {
486 |     VaultData storage s = _loadStorageSlot();
487 |     return _totalAssets(s);
488 |   }
489 | 
490 |   function _totalAssets(VaultData storage s) internal view returns (uint256) {
491 |     uint256 delta_t = block.timestamp - s.last;
492 |     return uint256(s.slope).mulDivDown(delta_t, 1) + uint256(s.yIntercept);
493 |   }
